        || set.source_local.as_ref() != Some(new_local)
        || set.source.as_ref() != Some(&new.root)
        || set.source_node.as_ref() != Some(&set_root_argument.value.node_id)
        || set.source_type.as_ref() != Some(&set_root_argument.value.ty)
