    #[test]
    fn map_root_checker_contains_receipts_are_static_borrowing_and_fail_closed() {
        let accepted = parse(
            r#"
func main() -> i32 {
    let first = map_new()
    let root = map_set(first, "answer", 42)
    let present = has_key(root, "answer")
    let missing = has_key(root, "missing")
    drop(root)
    0
}
"#,
        );
        let program = crate::core::check_program(&accepted).expect("static MapRoot contains");
        let analysis = program
            .resource_analysis(&NodeId("function:main".into()))
            .expect("MapRoot resource analysis");
        assert_eq!(
            analysis
                .map_root_actions
                .iter()
                .map(|action| action.kind)
                .collect::<Vec<_>>(),
            [
                MapRootActionKind::New,
                MapRootActionKind::Set,
                MapRootActionKind::Contains,
                MapRootActionKind::Contains,
                MapRootActionKind::Drop,
            ]
        );
        let set = &analysis.map_root_actions[1];
        let contains_present = &analysis.map_root_actions[2];
        let contains_missing = &analysis.map_root_actions[3];
        let drop = &analysis.map_root_actions[4];
        assert_eq!(contains_present.key.as_deref(), Some("answer"));
        assert_eq!(contains_missing.key.as_deref(), Some("missing"));
        assert_eq!(contains_present.root, set.root);
        assert_eq!(contains_missing.root, set.root);
        assert_eq!(drop.root, set.root);
        assert_eq!(contains_present.local, set.local);
        assert_eq!(contains_missing.local, set.local);
        assert_eq!(drop.local, set.local);
        assert!(contains_present.value.is_none());
        assert!(contains_present.source.is_none());
        assert!(contains_present.value_type.is_none());

        let dynamic_key = parse(
            r#"
func main() -> i32 {
    let root = map_new()
    let key = "answer"
    let present = has_key(root, key)
    drop(root)
    0
}
"#,
        );
        let program = crate::core::check_program(&dynamic_key).expect("legacy Map stays checkable");
        let analysis = program
            .resource_analysis(&NodeId("function:main".into()))
            .expect("MapRoot resource analysis");
        assert!(analysis.map_root_actions.is_empty());
        assert_eq!(analysis.map_root_new_attempts.len(), 1);

        let nul_key = parse(
            r#"
func main() -> i32 {
    let root = map_new()
    let present = has_key(root, "bad\0key")
    drop(root)
    0
}
"#,
        );
        match crate::core::check_program(&nul_key) {
            Ok(program) => {
                let analysis = program
                    .resource_analysis(&NodeId("function:main".into()))
                    .expect("MapRoot resource analysis");
                assert!(analysis
                    .map_root_actions
                    .iter()
                    .all(|action| action.kind != MapRootActionKind::Contains));
            }
            Err(errors) => assert!(!errors.is_empty(), "NUL key is rejected during checking"),
        }
    }

    #[test]
    fn map_root_remove_checker_receipts_consume_and_reissue_one_root_chain() {
        let file = parse(
            r#"
func main() -> i32 {
    let first = map_new()
    let inserted = map_set(first, "remove", "payload")
    let with_keep = map_set(inserted, "keep", "stay")
    let removed = map_remove(with_keep, "remove")
    let size = map_size(removed)
    drop(removed)
    size
}
"#,
        );
        let program = crate::core::check_program(&file).expect("closed Map-root Remove lifecycle");
        let analysis = program
            .resource_analysis(&NodeId("function:main".into()))
            .expect("Map-root resource analysis");
        let actions = &analysis.map_root_actions;
        assert_eq!(
            actions.iter().map(|action| action.kind).collect::<Vec<_>>(),
            [
                MapRootActionKind::New,
                MapRootActionKind::Set,
                MapRootActionKind::Set,
                MapRootActionKind::Remove,
                MapRootActionKind::Size,
                MapRootActionKind::Drop,
            ]
        );
        assert_eq!(actions[3].key.as_deref(), Some("remove"));
        assert_eq!(actions[3].source.as_ref(), Some(&actions[2].root));
        assert_eq!(actions[3].source_local.as_ref(), Some(&actions[2].local));
        assert_eq!(actions[3].root, actions[4].root);
        assert_eq!(actions[3].local, actions[4].local);
        assert_eq!(actions[4].root, actions[5].root);

        let temporary = parse(
            r#"
func main() -> i32 {
    let removed = map_remove(map_new(), "missing")
    let size = map_size(removed)
    drop(removed)
    size
}
"#,
        );
        let program = crate::core::check_program(&temporary)
            .expect("temporary MapRoot source is consumed by Remove");
        let analysis = program
            .resource_analysis(&NodeId("function:main".into()))
            .expect("temporary Map-root analysis");
        assert_eq!(
            analysis
                .map_root_actions
                .iter()
                .map(|action| action.kind)
                .collect::<Vec<_>>(),
            [
                MapRootActionKind::New,
                MapRootActionKind::Remove,
                MapRootActionKind::Size,
                MapRootActionKind::Drop,
            ]
        );
        assert_eq!(
            analysis.map_root_actions[0].root,
            analysis.map_root_actions[1].source.clone().unwrap()
        );
    }

    #[test]
    fn map_root_remove_dynamic_key_and_reuse_withhold_canonical_receipts() {
        for source in [
            r#"
func main() -> i32 {
    let root = map_new()
    let inserted = map_set(root, "answer", 42)
    let key = "answer"
    let removed = map_remove(inserted, key)
    drop(removed)
    0
}
"#,
            r#"
func main() -> i32 {
    let root = map_new()
    let inserted = map_set(root, "answer", 42)
    let removed = map_remove(inserted, "answer")
    let again = map_remove(inserted, "answer")
    let size = map_size(again)
    drop(removed)
    drop(again)
    size
}
"#,
        ] {
            let file = parse(source);
            let program = crate::core::check_program(&file)
                .expect("unsupported persistent Map source remains type-correct");
            let analysis = program
                .resource_analysis(&NodeId("function:main".into()))
                .expect("Map-root analysis");
            assert!(
                analysis.map_root_actions.is_empty(),
                "unsupported Remove shape must withhold the entire ownership receipt"
            );
            assert_eq!(
                crate::core::mir::classify_canonical_mir_route_admission(&program).map_root,
                crate::core::mir::MapRootAdmission::OutsideProfile,
                "unsupported persistent Map usage must remain on the compatibility route"
            );
        }
    }

    #[test]
    fn ordinary_map_owned_any_v2_values_result_producer_caller_fixture_binds_every_new_set_path() {
        use crate::core::ownership::{
            OrdinaryMapOwnedAnyV2ValuesResultProducerCallerProfileVersion as CallerProfile,
            OrdinaryMapOwnedAnyV2ValuesResultProducerProfileVersion as ProducerProfile,
        };

        let source = include_str!(
            "../../../tests/fixtures/mir_ordinary_map_owned_any_v2_values_producer_caller.mimi"
        );
        let mut hash_command = std::process::Command::new("sha256sum")
            .arg("-")
            .stdin(std::process::Stdio::piped())
            .stdout(std::process::Stdio::piped())
            .spawn()
            .expect("sha256sum is available for source-bound Values producer checks");
        use std::io::Write as _;
        hash_command
            .stdin
            .take()
            .expect("sha256sum stdin is piped")
            .write_all(source.as_bytes())
            .expect("write source-bound Values producer fixture to sha256sum");
        let hash_output = hash_command
            .wait_with_output()
            .expect("wait for source-bound Values producer fixture SHA-256");
        assert!(
            hash_output.status.success(),
            "sha256sum failed: {}",
            String::from_utf8_lossy(&hash_output.stderr)
        );
        let source_sha256 = String::from_utf8(hash_output.stdout)
            .expect("sha256sum output is UTF-8")
            .split_whitespace()
            .next()
            .expect("sha256sum prints a digest")
            .to_owned();
        assert_eq!(
            source_sha256, "79a48cbba5e154452f3f6bfb1ca5dde41b86b89689df350f2dad17169753519e",
            "the third Result producer fixture is source-bound"
        );

        let checked = crate::core::check_program(&parse_stdlib(source))
            .expect("the complete producer-caller Result fixture must check");
        let producer_owner = NodeId("function:snapshot_values".into());
        let producer = checked
            .callables()
            .get(&producer_owner)
            .expect("source-bound producer callable");
        let receipt = producer
            .resources
            .ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .and_then(|cfg| cfg.values_result_producer_receipt.as_ref())
            .expect("the producer-caller fixture has the exact Result branch receipt");
        assert_eq!(receipt.profile_version, ProducerProfile::V1);
        assert_eq!(
            receipt
                .paths
                .iter()
                .map(|path| path.drops.len())
                .collect::<Vec<_>>(),
            [1, 2, 3],
            "map_new Err, map_set Err, and Values success settle all live owners"
        );
        let branch_drop_names = receipt
            .paths
            .iter()
            .map(|path| {
                let mut names = path
                    .drops
                    .iter()
                    .map(|drop| {
                        producer
                            .body
                            .locals
                            .get(&drop.local)
                            .expect("branch Drop names a declared owner")
                            .display_name
                            .clone()
                    })
                    .collect::<Vec<_>>();
                names.sort();
                (path.kind, names)
            })
            .collect::<Vec<_>>();
        assert_eq!(
            branch_drop_names,
            [
                (
                    crate::core::ownership::OrdinaryMapOwnedAnyV2ValuesResultPathKind::EmptyList,
                    vec!["payload".to_owned()],
                ),
                (
                    crate::core::ownership::OrdinaryMapOwnedAnyV2ValuesResultPathKind::EmptyList,
                    vec!["empty".to_owned(), "payload".to_owned()],
                ),
                (
                    crate::core::ownership::OrdinaryMapOwnedAnyV2ValuesResultPathKind::ValuesSnapshot,
                    vec!["empty".to_owned(), "payload".to_owned(), "root".to_owned()],
                ),
            ],
            "the three terminal paths settle exactly their live payload and Map-root obligations"
        );
        let replayed = values_result_branch::collect(
            &producer.cfg,
            &producer.body,
            &producer.signature,
            checked.resolved_types(),
        )
        .expect("the third source's full Result CFG must independently replay");
        assert_eq!(
            replayed.receipt, *receipt,
            "the published receipt is exactly reproducible from this source CFG"
        );

        let producer_cfg_receipt = producer
            .resources
            .ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .expect("producer has a complete Map/Any CFG receipt");
        let caller_receipt = producer_cfg_receipt
            .values_result_producer_caller_receipt
            .as_ref()
            .expect("the Result producer has an independent one-length caller receipt");
        assert_eq!(caller_receipt.profile_version, CallerProfile::V1);
        assert_eq!(
            caller_receipt.profile_version.canonical_text(),
            "ordinary-map-owned-any-v2-values-result-producer-caller-v1-one-length-return"
        );
        assert_eq!(caller_receipt.producer_result, *receipt);
        assert_eq!(caller_receipt.producer_owner, producer_owner);
        assert_eq!(caller_receipt.producer_target, producer_owner);
        assert_eq!(
            caller_receipt.caller_owner,
            NodeId("function:direct_caller".into())
        );
        assert_eq!(
            caller_receipt.snapshot_local,
            caller_receipt.len.receiver_local
        );
        assert_eq!(caller_receipt.owner_drop_place_index, 0);
        assert_eq!(
            caller_receipt.caller_return_type,
            caller_receipt.len.result_type
        );
        assert_eq!(
            caller_receipt.producer_values_operation,
            receipt.values_operation
        );
        assert_eq!(
            caller_receipt.producer_success_result,
            receipt.success_result
        );

        let assert_incomplete_v2_rejected =
            |mutated: &str, expect_producer: bool, message: &str| {
                let checked = crate::core::check_program(&parse_stdlib(mutated))
                    .expect("source checks before withholding canonical route receipt");
                let producer_cfg = checked
                    .resource_analysis(&producer_owner)
                    .and_then(|analysis| analysis.ordinary_map_owned_any_v2_cfg_receipt.as_ref());
                assert_eq!(
                    producer_cfg
                        .and_then(|cfg| cfg.values_result_producer_receipt.as_ref())
                        .is_some(),
                    expect_producer,
                    "{message}: producer receipt expectation"
                );
                assert!(
                    producer_cfg
                        .and_then(|cfg| cfg.values_result_producer_caller_receipt.as_ref())
                        .is_none(),
                    "{message}: caller receipt must be withheld"
                );
                assert_eq!(
                    crate::core::mir::classify_canonical_mir_route_admission(&checked)
                        .ordinary_map_owned_any_v2,
                    crate::core::mir::OrdinaryMapOwnedAnyV2Admission::IncompleteCoverage,
                    "{message}: must remain in fail-closed IncompleteCoverage"
                );
                assert!(
                    crate::core::mir::materialize_canonical_mir_route(&checked, None).is_err(),
                    "{message}: missing receipt must remain a hard failure, not a legacy retry"
                );
            };

        let missing_new_error_drop = source.replace(
            "        Err(status) => {\n            drop(payload)\n            []\n        },",
            "        Err(status) => [],",
        );
        assert_ne!(missing_new_error_drop, source);
        assert_incomplete_v2_rejected(
            &missing_new_error_drop,
            false,
            "map_new Err must settle the payload before returning an empty list",
        );

        let missing_set_error_root_drop = source.replace(
            "                Err(status) => {\n                    drop(empty)\n                    drop(payload)\n                    []\n                },",
            "                Err(status) => {\n                    drop(payload)\n                    []\n                },",
        );
        assert_ne!(missing_set_error_root_drop, source);
        assert_incomplete_v2_rejected(
            &missing_set_error_root_drop,
            false,
            "map_set Err must settle the surviving Map root",
        );

        let missing_set_error_payload_drop = source.replace(
            "                Err(status) => {\n                    drop(empty)\n                    drop(payload)\n                    []\n                },",
            "                Err(status) => {\n                    drop(empty)\n                    []\n                },",
        );
        assert_ne!(missing_set_error_payload_drop, source);
        assert_incomplete_v2_rejected(
            &missing_set_error_payload_drop,
            false,
            "map_set Err must settle the source String payload",
        );

        let duplicate_set_error_payload_drop = source.replace(
            "                    drop(payload)\n                    []\n                },",
            "                    drop(payload)\n                    drop(payload)\n                    []\n                },",
        );
        assert_ne!(duplicate_set_error_payload_drop, source);
        assert_incomplete_v2_rejected(
            &duplicate_set_error_payload_drop,
            false,
            "a Result path cannot settle the same payload owner twice",
        );

        let duplicate_set_error_root_drop = source.replace(
            "                    drop(empty)\n                    drop(payload)\n                    []\n                },",
            "                    drop(empty)\n                    drop(empty)\n                    drop(payload)\n                    []\n                },",
        );
        assert_ne!(duplicate_set_error_root_drop, source);
        assert_incomplete_v2_rejected(
            &duplicate_set_error_root_drop,
            false,
            "a Result path cannot settle the same Map root twice",
        );

        let missing_caller_snapshot_drop = source.replace(
            "    let count = snapshot.len()\n    drop(snapshot)\n    count",
            "    let count = snapshot.len()\n    count",
        );
        assert_ne!(missing_caller_snapshot_drop, source);
        assert_incomplete_v2_rejected(
            &missing_caller_snapshot_drop,
            true,
            "the Values snapshot owner must be dropped in its direct caller",
        );
    }

    #[test]
    fn map_root_checker_receipts_keep_interleaved_roots_and_utf8_keys_distinct() {
        let file = parse(
            r#"
func main() -> i32 {
    let left = map_new()
    let right = map_new()
    let left_updated = map_set(left, "café🧪", 1 + 41)
    let right_updated = map_set(right, "🗺️", map_size(left_updated))
    let right_size = map_size(right_updated)
    drop(left_updated)
    drop(right_updated)
    right_size
}
"#,
        );
        let program = crate::core::check_program(&file).expect("closed Map-root lifecycles");
        let analysis = program
            .resource_analysis(&NodeId("function:main".into()))
            .expect("Map-root resource analysis");
        let actions = &analysis.map_root_actions;
        assert_eq!(
            actions.iter().map(|action| action.kind).collect::<Vec<_>>(),
            [
                MapRootActionKind::New,
                MapRootActionKind::New,
                MapRootActionKind::Set,
                MapRootActionKind::Size,
                MapRootActionKind::Set,
                MapRootActionKind::Size,
                MapRootActionKind::Drop,
                MapRootActionKind::Drop,
            ]
        );

        let left_root = &actions[0].root;
        let right_root = &actions[1].root;
        assert_ne!(left_root, right_root);
        assert_eq!(actions[2].source.as_ref(), Some(left_root));
        assert_eq!(actions[2].key.as_deref(), Some("café🧪"));
        assert_eq!(actions[3].root, actions[2].root);
        assert_eq!(actions[4].source.as_ref(), Some(right_root));
        assert_eq!(actions[4].key.as_deref(), Some("🗺️"));
        assert_eq!(actions[5].root, actions[4].root);
        assert_eq!(actions[6].root, actions[2].root);
        assert_eq!(actions[7].root, actions[4].root);
        assert_eq!(actions[2].local, actions[3].local);
        assert_eq!(actions[4].local, actions[5].local);
    }

    #[test]
    fn map_root_checker_withholds_mixed_payload_type_chain() {
        for source in [
            r#"
func main() -> i32 {
    let root = map_new()
    let integer_value = map_set(root, "answer", 42)
    let mixed_value = map_set(integer_value, "label", "forty-two")
    drop(mixed_value)
    0
}
"#,
            r#"
func main() -> i32 {
    let root = map_new()
    let string_value = map_set(root, "label", "forty-two")
    let mixed_value = map_set(string_value, "answer", 42)
    drop(mixed_value)
    0
}
"#,
        ] {
            let file = parse(source);
            let program = crate::core::check_program(&file)
                .expect("legacy Any Map semantics remain available for mixed payloads");
            let analysis = program
                .resource_analysis(&NodeId("function:main".into()))
                .expect("MapRoot resource analysis");
            assert_eq!(analysis.map_root_new_attempts.len(), 1);
            assert!(
                analysis.map_root_actions.is_empty(),
                "a root chain that changes payload TypeDesc must not receive partial MapRoot authority"
            );
            assert!(
                analysis.map_any_owner_actions.is_empty(),
                "a root chain that changes payload TypeDesc must not receive partial MapAnyOwner v1 authority"
            );
        }
    }

