    #[test]
    fn static_key_get_receipt_selects_newest_same_key_set() {
        let receipt = ordinary_map_any_cfg_receipt(
            r#"
func main() -> i32 {
    let empty = map_new()
    let first = map_set(empty, "same", 11)
    let second = map_set(first, "same", 22)
    let pair = map_get(second, "same")
    let value = unpack_i32(pair.1)
    drop(pair)
    drop(empty)
    drop(first)
    drop(second)
    value
}
"#,
        );
        let [credential] = receipt.static_key_get_receipts.as_slice() else {
            panic!("one exact static-key GetAny credential is expected");
        };
        let set_actions = receipt
            .actions
            .iter()
            .filter(|action| action.kind == OrdinaryMapOwnedAnyV2ActionKind::Set)
            .collect::<Vec<_>>();
        assert_eq!(set_actions.len(), 2);
        assert_eq!(
            credential.selected_winning_set_action.as_ref(),
            Some(set_actions[1])
        );
        assert_eq!(
            credential.query_digest,
            blake3::hash(b"same").to_hex().to_string()
        );
        assert_eq!(
            credential.payload_source,
            crate::core::ownership::OrdinaryMapOwnedAnyV2StaticKeyGetPayloadSource::SelectedSet {
                value_type: crate::core::ir::primitive_type_id(crate::core::PrimitiveType::I32),
            }
        );
    }

    #[test]
    fn static_key_get_receipts_select_sets_by_distinct_key() {
        let receipt = ordinary_map_any_cfg_receipt(
            r#"
func main() -> i32 {
    let empty = map_new()
    let left = map_set(empty, "left", 7)
    let right = map_set(left, "right", 8)
    let left_pair = map_get(right, "left")
    let left_value = unpack_i32(left_pair.1)
    drop(left_pair)
    let right_pair = map_get(right, "right")
    let right_value = unpack_i32(right_pair.1)
    drop(right_pair)
    drop(empty)
    drop(left)
    drop(right)
    left_value + right_value
}
"#,
        );
        assert_eq!(receipt.static_key_get_receipts.len(), 2);
        for key in ["left", "right"] {
            let digest = blake3::hash(key.as_bytes()).to_hex().to_string();
            let credential = receipt
                .static_key_get_receipts
                .iter()
                .find(|receipt| receipt.query_digest == digest)
                .expect("credential for each static query key");
            let winner = credential
                .selected_winning_set_action
                .as_ref()
                .expect("each query selects a Set");
            let expected = receipt
                .actions
                .iter()
                .find(|action| {
                    action.kind == OrdinaryMapOwnedAnyV2ActionKind::Set
                        && action.key_static_digest.as_deref() == Some(digest.as_str())
                })
                .expect("key-specific persistent Set");
            assert_eq!(winner.point, expected.point);
        }
    }

