    #[test]
    fn ordinary_map_owned_any_v2_keys_snapshot_checks_owned_escape_and_source_order() {
        let source = parse(include_str!(
            "../../../tests/fixtures/mir_ordinary_map_any_owner_v2_keys_snapshot.mimi"
        ));
        let checked = crate::core::check_program(&source)
            .expect("the exact owned keys snapshot profile should typecheck");
        let owner = NodeId("function:main".into());
        let analysis = checked
            .resource_analysis(&owner)
            .expect("keys source resource analysis");
        let cfg_receipt = analysis
            .ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .expect("exact keys snapshot has a V2 Checker receipt");
        let receipt = cfg_receipt
            .keys_snapshot_receipts
            .first()
            .expect("one exact Checker L1 keys snapshot receipt");

        assert_eq!(
            receipt.profile_version,
            OrdinaryMapOwnedAnyV2KeysSnapshotProfileVersion::V1
        );
        assert_eq!(receipt.owner, owner);
        assert_eq!(receipt.static_key_utf8, b"answer");
        assert_eq!(
            receipt.static_key_digest,
            blake3::hash(b"answer").to_hex().to_string()
        );
        assert_eq!(
            receipt.index_type,
            crate::core::ir::primitive_type_id(crate::core::PrimitiveType::I32)
        );
        assert_eq!(
            receipt.key_type,
            crate::core::ir::primitive_type_id(crate::core::PrimitiveType::String)
        );
        assert_eq!(
            analysis
                .ordinary_map_owned_any_v2_operation_attempts
                .iter()
                .filter(|attempt| attempt.kind == OrdinaryMapOwnedAnyV2AttemptKind::Keys)
                .count(),
            1,
            "the supported keys attempt remains visible beside its action"
        );

        let cfg = checked.callable_cfg(&owner).expect("keys source CFG");
        let keys_order = ordinary_map_owned_any_v2_cfg_point_index(cfg, &receipt.keys_operation)
            .expect("keys call point");
        let root_drop_order =
            ordinary_map_owned_any_v2_cfg_point_index(cfg, &receipt.root_drop_point)
                .expect("root Drop point");
        let index_order = ordinary_map_owned_any_v2_cfg_point_index(cfg, &receipt.index_projection)
            .expect("literal index projection point");
        let snapshot_drop_order =
            ordinary_map_owned_any_v2_cfg_point_index(cfg, &receipt.snapshot_drop_point)
                .expect("snapshot Drop point");
        let print_order = ordinary_map_owned_any_v2_cfg_point_index(cfg, &receipt.observation_call)
            .expect("owned String print point");
        let key_drop_order =
            ordinary_map_owned_any_v2_cfg_point_index(cfg, &receipt.key_drop_point)
                .expect("owned String Drop point");
        assert!(
            keys_order < root_drop_order
                && root_drop_order < index_order
                && index_order < snapshot_drop_order
                && snapshot_drop_order < print_order
                && print_order < key_drop_order,
            "the source Map dies before index extraction; the copied key is printed after both owners die"
        );

        let action = analysis
            .ordinary_map_owned_any_v2_actions
            .iter()
            .find(|action| action.kind == OrdinaryMapOwnedAnyV2ActionKind::Keys)
            .expect("Keys has its exact V2 Map-root action");
        assert_eq!(action.point, receipt.keys_operation);
        assert_eq!(action.local, receipt.source_local);
        assert_eq!(action.root, receipt.source);
        assert_eq!(action.result_local.as_ref(), Some(&receipt.snapshot_local));
        assert_eq!(action.result_type.as_ref(), Some(&receipt.snapshot_type));
        assert!(matches!(
            checked.resolved_types().get(&receipt.snapshot_type),
            Some(ResolvedType::Nominal { item, arguments, .. })
                if item.as_str() == "builtin:type:List"
                    && arguments.as_slice()
                        == [crate::core::ir::primitive_type_id(crate::core::PrimitiveType::String)]
        ));
    }

    #[test]
    fn ordinary_map_owned_any_v2_keys_snapshot_withholds_nonexact_shapes() {
        let cases = [
            (
                "dynamic index",
                r#"func main() -> i32 {
    let empty = map_new()
    let root = map_set(empty, "answer", 41)
    let snapshot = keys(root)
    drop(empty)
    drop(root)
    let index = 0
    let key = snapshot[index]
    drop(snapshot)
    println(key)
    drop(key)
    0
}"#,
            ),
            (
                "unrelated root",
                r#"func main() -> i32 {
    let empty = map_new()
    let root = map_set(empty, "answer", 41)
    let unrelated = map_new()
    let snapshot = keys(unrelated)
    drop(empty)
    drop(root)
    drop(unrelated)
    let key = snapshot[0]
    drop(snapshot)
    println(key)
    drop(key)
    0
}"#,
            ),
            (
                "repeated snapshot Drop",
                r#"func main() -> i32 {
    let empty = map_new()
    let root = map_set(empty, "answer", 41)
    let snapshot = keys(root)
    drop(empty)
    drop(root)
    let key = snapshot[0]
    drop(snapshot)
    drop(snapshot)
    println(key)
    drop(key)
    0
}"#,
            ),
            (
                "key escapes the callable",
                r#"func escape_key() -> string {
    let empty = map_new()
    let root = map_set(empty, "answer", 41)
    let snapshot = keys(root)
    drop(empty)
    drop(root)
    let key = snapshot[0]
    drop(snapshot)
    key
}
func main() -> i32 {
    let escaped = escape_key()
    println(escaped)
    drop(escaped)
    0
}"#,
            ),
            (
                "key alias",
                r#"func main() -> i32 {
    let empty = map_new()
    let root = map_set(empty, "answer", 41)
    let snapshot = keys(root)
    drop(empty)
    drop(root)
    let key = snapshot[0]
    let alias = key
    drop(snapshot)
    println(alias)
    drop(key)
    drop(alias)
    0
}"#,
            ),
        ];

        for (label, source) in cases {
            match crate::core::check_program(&parse(source)) {
                Err(errors) => assert!(!errors.is_empty(), "{label}: diagnostics are visible"),
                Ok(checked) => {
                    let analysis = checked
                        .callables()
                        .keys()
                        .filter_map(|owner| checked.resource_analysis(owner))
                        .find(|analysis| {
                            analysis
                                .ordinary_map_owned_any_v2_operation_attempts
                                .iter()
                                .any(|attempt| {
                                    attempt.kind == OrdinaryMapOwnedAnyV2AttemptKind::Keys
                                })
                        })
                        .unwrap_or_else(|| panic!("{label}: Keys attempt remains visible"));
                    assert!(
                        analysis.ordinary_map_owned_any_v2_cfg_receipt.is_none(),
                        "{label}: non-exact source shape must not receive a keys receipt"
                    );
                    if matches!(label, "key alias" | "key escapes the callable") {
                        let owner = if label == "key alias" {
                            NodeId("function:main".into())
                        } else {
                            NodeId("function:escape_key".into())
                        };
                        let body = checked
                            .resolved_body(&owner)
                            .unwrap_or_else(|| panic!("{label}: checked source body is available"));
                        let bound_local = |statement: &crate::core::ir::ResolvedStmt| {
                            let crate::core::ir::ResolvedStmtKind::Bind {
                                pattern:
                                    crate::core::ir::ResolvedPattern {
                                        kind:
                                            crate::core::ir::ResolvedPatternKind::Binding {
                                                local,
                                                by_reference: None,
                                            },
                                        ..
                                    },
                                initializer: Some(_),
                            } = &statement.kind
                            else {
                                panic!("{label}: fixture binding is directly represented");
                            };
                            local.clone()
                        };
                        let key_local = bound_local(&body.root.statements[5]);
                        let key_uses =
                            ordinary_map_owned_any_v2_local_source_uses(body, &key_local);
                        if label == "key alias" {
                            let crate::core::ir::ResolvedStmtKind::Bind {
                                initializer: Some(alias_initializer),
                                ..
                            } = &body.root.statements[6].kind
                            else {
                                panic!("key alias fixture has an alias binding");
                            };
                            assert_eq!(key_uses.loads.len(), 1);
                            assert_eq!(
                                key_uses.loads[0].node, alias_initializer.node_id,
                                "the extracted String's sole read creates an alias; println observes a different local"
                            );
                        } else {
                            let result = body
                                .root
                                .result
                                .as_deref()
                                .expect("escape fixture returns the extracted String");
                            assert!(matches!(
                                &result.kind,
                                crate::core::ir::ResolvedExprKind::Load(place)
                                    if place.base == key_local && place.projections.is_empty()
                            ));
                            assert!(key_uses.places.is_empty());
                            assert_eq!(key_uses.loads.len(), 1);
                            assert_eq!(key_uses.loads[0].node, result.node_id);
                        }
                    }
                }
            }
        }
    }

    #[test]
    fn ordinary_map_owned_any_v2_receipts_direct_temporary_empty_get_any_root() {
        let source = parse(
            r#"
func main() -> i32 {
    let pair = map_get(map_new(), "missing")
    drop(pair)
    0
}
"#,
        );
        let checked = crate::core::check_program(&source).expect("temporary-root GetAny checks");
        let analysis = checked
            .resource_analysis(&NodeId("function:main".into()))
            .expect("temporary-root resource analysis");
        let receipt = analysis
            .ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .expect("temporary-root GetAny has a complete V2 receipt");
        let [root] = receipt.temporary_root_receipts.as_slice() else {
            panic!("the immediate map_new source has one compiler-owned root receipt");
        };
        assert_eq!(root.construction, root.source_node);
        assert_eq!(root.root_type, root.source_type);
        assert_eq!(
            root.settlement,
            OrdinaryMapOwnedAnyV2RootSettlementKind::ImmediateGetAnyDrop
        );
        assert_eq!(root.get_any, root.settlement_point);
        let actions = receipt
            .actions
            .iter()
            .filter(|action| action.local == root.local)
            .collect::<Vec<_>>();
        assert_eq!(
            actions.iter().map(|action| action.kind).collect::<Vec<_>>(),
            vec![
                OrdinaryMapOwnedAnyV2ActionKind::New,
                OrdinaryMapOwnedAnyV2ActionKind::GetAny,
                OrdinaryMapOwnedAnyV2ActionKind::Drop,
            ]
        );
        assert!(!receipt.attempts.iter().any(|attempt| {
            attempt.kind == OrdinaryMapOwnedAnyV2AttemptKind::ScopeDrop
                && attempt.receiver_local.as_ref() == Some(&root.local)
        }));
        assert_eq!(receipt.result_receipts.len(), 1);
        assert_eq!(
            receipt.result_receipts[0].settlement,
            OrdinaryMapOwnedAnyV2ResultSettlementKind::ExplicitDrop
        );
    }

    #[test]
    fn ordinary_map_owned_any_v2_if_diamond_carries_equal_root_and_result_owners_to_join() {
        let source = parse(
            r#"
func main() -> i32 {
    let root = map_new()
    let pair = map_get(root, "missing")
    let snapshot = values(root)
    let flag = true
    let observed = if flag {
        map_size(root)
    } else {
        map_size(root)
    }
    drop(pair)
    drop(snapshot)
    drop(root)
    observed
}
"#,
        );
        let checked = crate::core::check_program(&source).expect("V2 if diamond checks");
        let analysis = checked
            .resource_analysis(&NodeId("function:main".into()))
            .expect("V2 if diamond ownership analysis");
        let cfg = checked
            .callable_cfg(&NodeId("function:main".into()))
            .expect("V2 if diamond source CFG");
        assert!(
            analysis.ordinary_map_owned_any_v2_cfg_receipt.is_some(),
            "balanced V2 if diamond has a Checker receipt; cfg={cfg:#?}; actions={:#?}; attempts={:#?}",
            analysis.ordinary_map_owned_any_v2_actions,
            analysis.ordinary_map_owned_any_v2_operation_attempts
        );
        let receipt = analysis
            .ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .expect("receipt was checked above");
        let flow = receipt.flow.as_ref().expect("diamond has V2 edge facts");
        assert_eq!(flow.reachable_blocks.len(), 4);
        assert_eq!(flow.arm_edges.len(), 2);
        let split = &flow.live_owners_out[&flow.split];
        assert_eq!(split.len(), 3, "one root plus GetAny and Values owners");
        assert!(split.iter().any(|owner| matches!(
            owner,
            crate::core::OrdinaryMapOwnedAnyV2LiveOwner::Root { .. }
        )));
        assert_eq!(
            split
                .iter()
                .filter(|owner| matches!(
                    owner,
                    crate::core::OrdinaryMapOwnedAnyV2LiveOwner::Result { .. }
                ))
                .count(),
            2
        );
        for edge in &flow.arm_edges {
            assert_eq!(&flow.live_owners_on_edge[edge], split);
            let target = &flow.reachable_edges[edge].to;
            assert_eq!(&flow.live_owners_in[target], split);
        }
        assert!(flow.live_owners_out[&flow.join].is_empty());
        assert!(receipt.result_receipts.iter().all(|result| {
            result.settlement == OrdinaryMapOwnedAnyV2ResultSettlementKind::ExplicitDrop
                && flow.reachable_blocks[&flow.join]
                    .points
                    .iter()
                    .any(|(point, _)| Some(point) == result.settlement_point.as_ref())
        }));
    }

    #[test]
    fn ordinary_map_owned_any_v2_branch_local_persistent_set_diamond_receipt_is_exact() {
        let source = include_str!(
            "../../../tests/fixtures/mir_branch_local_persistent_map_set_diamond_true.mimi"
        );
        let checked = crate::core::check_program(&parse(source))
            .expect("branch-local persistent Map Set source checks");
        let analysis = checked
            .resource_analysis(&NodeId("function:main".into()))
            .expect("ownership analysis");
        let receipt = analysis
            .ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .unwrap_or_else(|| {
                panic!(
                    "branch-local lifecycle receipt withheld; cfg={:#?}; actions={:#?}; attempts={:#?}",
                    checked.callable_cfg(&NodeId("function:main".into())),
                    analysis.ordinary_map_owned_any_v2_actions,
                    analysis.ordinary_map_owned_any_v2_operation_attempts
                )
            });
        let flow = receipt
            .flow
            .as_ref()
            .expect("the source has CFG flow facts");
        let crate::core::ownership::OrdinaryMapOwnedAnyV2CfgFlowProof::BranchLocalPersistentSetDiamondV1(
            branch,
        ) = &flow.proof
        else {
            panic!("the exact persistent Set diamond has its own proof variant");
        };

        assert_eq!(branch.owner, NodeId("function:main".into()));
        assert_eq!(branch.split, flow.split);
        assert_eq!(branch.outer_join, flow.join);
        assert_eq!(branch.arms.len(), 2);
        assert_eq!(branch.result_branches.len(), 3);
        assert_ne!(branch.payload_local, branch.base_local);
        assert_eq!(branch.base_new.kind, OrdinaryMapOwnedAnyV2ActionKind::New);
        assert_eq!(branch.base_new.local, branch.base_local);
        assert!(matches!(
            checked.resolved_types().get(&branch.payload_type),
            Some(ResolvedType::Nominal { item, arguments, .. })
                if !item.as_str().starts_with("builtin:type:") && arguments.is_empty()
        ));
        let base_owner = crate::core::OrdinaryMapOwnedAnyV2LiveOwner::Root {
            local: branch.base_local.clone(),
            resource: branch.base_new.root.clone(),
        };
        assert_eq!(receipt.actions.len(), 11);
        assert_eq!(receipt.attempts.len(), 11);
        assert_eq!(flow.live_owners_out[&flow.split].len(), 1);
        assert!(flow.live_owners_out[&flow.split].contains(&base_owner));
        assert!(flow.live_owners_in[&flow.join].is_empty());
        assert!(flow.live_owners_out[&flow.join].is_empty());

        let mut child_roots = BTreeSet::new();
        let mut payload_loads = BTreeSet::new();
        for (edge, arm) in &branch.arms {
            assert_eq!(edge, &arm.edge);
            assert_eq!(flow.reachable_edges[edge].to, arm.block);
            assert_eq!(flow.reachable_edges[&arm.join_edge].to, branch.join);
            assert_eq!(arm.set.kind, OrdinaryMapOwnedAnyV2ActionKind::Set);
            assert_eq!(arm.size.kind, OrdinaryMapOwnedAnyV2ActionKind::Size);
            assert_eq!(arm.drop.kind, OrdinaryMapOwnedAnyV2ActionKind::Drop);
            assert_eq!(arm.ok_base_drop.kind, OrdinaryMapOwnedAnyV2ActionKind::Drop);
            assert_eq!(
                arm.err_base_drop.kind,
                OrdinaryMapOwnedAnyV2ActionKind::Drop
            );
            assert_eq!(arm.size.local, arm.set.local);
            assert_eq!(arm.drop.local, arm.set.local);
            assert_eq!(arm.ok_base_drop.local, branch.base_local);
            assert_eq!(arm.err_base_drop.local, branch.base_local);
            assert_eq!(arm.set.source_local.as_ref(), Some(&branch.base_local));
            assert_eq!(arm.set.value.as_ref(), Some(&arm.payload_load));
            assert_eq!(arm.set.value_type.as_ref(), Some(&branch.payload_type));
            assert!(child_roots.insert(arm.set.root.clone()));
            assert!(payload_loads.insert(arm.payload_load.clone()));
            assert_eq!(flow.live_owners_in[&arm.block].len(), 1);
            assert_eq!(flow.live_owners_out[&arm.block].len(), 1);
            assert_eq!(flow.live_owners_on_edge[edge].len(), 1);
        }
        assert_eq!(child_roots.len(), 2);
        assert_eq!(payload_loads.len(), 2);

        let assert_unreceipted = |label: &str, candidate: String| {
            let checked = match crate::core::check_program(&parse(&candidate)) {
                Ok(checked) => checked,
                Err(errors) => {
                    assert!(!errors.is_empty(), "{label} is rejected with diagnostics");
                    return;
                }
            };
            let analysis = checked
                .resource_analysis(&NodeId("function:main".into()))
                .expect("negative source ownership analysis");
            let got_branch_local_receipt = analysis
                .ordinary_map_owned_any_v2_cfg_receipt
                .as_ref()
                .and_then(|receipt| receipt.flow.as_ref())
                .is_some_and(|flow| {
                    matches!(
                        &flow.proof,
                        crate::core::ownership::OrdinaryMapOwnedAnyV2CfgFlowProof::BranchLocalPersistentSetDiamondV1(_)
                    )
                });
            assert!(
                !got_branch_local_receipt,
                "{label} must not receive the narrow branch-local proof"
            );
        };
        assert_unreceipted(
            "non-record payload in one arm",
            source.replace(
                "map_set(base, \"right\", payload)",
                "map_set(base, \"right\", 7)",
            ),
        );
        assert_unreceipted(
            "different concrete record payload source in one arm",
            source
                .replace(
                    "    match map_new()",
                    "    let other_payload = Label { text: \"other\" }\n    match map_new()",
                )
                .replace(
                    "map_set(base, \"right\", payload)",
                    "map_set(base, \"right\", other_payload)",
                ),
        );
        assert_unreceipted(
            "size observes the base instead of its child",
            source.replace(
                "map_set(base, \"right\", payload) {\n                    Ok(child) => {\n                        map_size(child)",
                "map_set(base, \"right\", payload) {\n                    Ok(child) => {\n                        map_size(base)",
            ),
        );
        assert_unreceipted(
            "extra Map action in an arm",
            source.replace(
                "map_set(base, \"left\", payload) {\n                    Ok(child) => {\n                        map_size(child)",
                "map_set(base, \"left\", payload) {\n                    Ok(child) => {\n                        map_size(base)\n                        map_size(child)",
            ),
        );
        assert_unreceipted(
            "wrong action order",
            source.replace(
                "                        map_size(child)\n                        drop(child)",
                "                        drop(child)\n                        map_size(child)",
            ),
        );
        assert_unreceipted(
            "child root escapes its arm edge",
            source.replace("                        drop(child)\n", ""),
        );
        assert_unreceipted(
            "base root is not dropped in arm",
            source.replace("                        drop(base)\n", ""),
        );
        assert_unreceipted(
            "result owner crosses the split",
            source.replace(
                "            let flag = true",
                "            let snapshot = values(base)\n            drop(snapshot)\n            let flag = true",
            ),
        );
        assert_unreceipted(
            "nested branch CFG",
            source.replace(
                "                match map_set(base, \"left\", payload)",
                "                if flag { println(0) }\n                match map_set(base, \"left\", payload)",
            ),
        );
        assert_unreceipted(
            "loop CFG",
            source.replace(
                "                match map_set(base, \"left\", payload)",
                "                while false { println(0) }\n                match map_set(base, \"left\", payload)",
            ),
        );
    }

