    #[test]
    fn ordinary_map_owned_any_v2_scalar_tail_source_rejects_non_scalar_or_owner_work() {
        let source = r#"
func main() -> i32 {
    match map_new() {
        Ok(root) => {
            let pair = map_get(root, "missing")
            let found = pair.0
            drop(pair)
            drop(root)
            if found { 1 } else { 0 }
        }
        Err(status) => status,
    }
}
"#;
        let checked = crate::core::check_program(&parse(source)).unwrap();
        assert!(checked
            .resource_analysis(&NodeId("function:main".into()))
            .unwrap()
            .ordinary_map_owned_any_v2_cfg_receipt
            .is_some());
        for (label, candidate) in [
            (
                "late result settlement",
                source
                    .replace("            drop(pair)\n", "")
                    .replace(
                        "            if found { 1 } else { 0 }",
                        "            let n = if found { 1 } else { 0 }\n            drop(pair)\n            n",
                    ),
            ),
            (
                "tail call",
                source.replace(
                    "if found { 1 }",
                    "if found {\n                println(1)\n                1\n            }",
                ),
            ),
            (
                "tail projection",
                source
                    .replace("            drop(pair)\n", "")
                    .replace(
                        "            if found { 1 } else { 0 }",
                        "            let out = if pair.0 { 1 } else { 0 }\n            drop(pair)\n            out",
                    ),
            ),
            (
                "match",
                source.replace(
                    "if found { 1 } else { 0 }",
                    "match found { true => 1, false => 0 }",
                ),
            ),
            (
                "loop",
                source.replace(
                    "            if found { 1 } else { 0 }",
                    "            while false { println(1) }\n            if found { 1 } else { 0 }",
                ),
            ),
        ] {
            let checked = crate::core::check_program(&parse(&candidate)).unwrap_or_else(|errors| {
                panic!("{label} source must reach the CFG gate: {errors:?}")
            });
            let analysis = checked
                .resource_analysis(&NodeId("function:main".into()))
                .unwrap();
            assert!(
                analysis.ordinary_map_owned_any_v2_cfg_receipt.is_none(),
                "{label}"
            );
            assert!(
                !analysis
                    .ordinary_map_owned_any_v2_operation_attempts
                    .is_empty(),
                "{label} keeps its census"
            );
        }
    }

    #[test]
    fn ordinary_map_owned_any_v2_scalar_tail_string_drop_is_exact_last_source_use() {
        let source = r#"
func main() -> i32 {
    let key = "missing"
    match map_new() {
        Ok(root) => {
            let pair = map_get(root, key)
            let found = pair.0
            drop(pair)
            drop(root)
            drop(key)
            if found { 1 } else { 0 }
        }
        Err(status) => {
            drop(key)
            status
        }
    }
}
"#;
        let checked = crate::core::check_program(&parse(source)).unwrap();
        let analysis = checked
            .resource_analysis(&NodeId("function:main".into()))
            .unwrap();
        let receipt = analysis
            .ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .unwrap();
        let tail = receipt
            .settled_scalar_tail()
            .expect("scalar source authority");
        assert_eq!(tail.string_drops.len(), 1);
        assert!(tail
            .string_drops
            .values()
            .all(|drop| drop.loads.iter().all(|(_, rank)| *rank < drop.point_rank)));
        for (label, candidate) in [
            (
                "load after Drop in entry",
                source
                    .replace("            drop(key)\n", "")
                    .replace("    match map_new()", "    drop(key)\n    match map_new()"),
            ),
            (
                "load after Drop in branch",
                source.replace(
                    "if found { 1 } else { 0 }",
                    "if found { if key == \"missing\" { 1 } else { 2 } } else { 0 }",
                ),
            ),
            (
                "repeated Drop",
                source.replace(
                    "            drop(key)\n            if found",
                    "            drop(key)\n            drop(key)\n            if found",
                ),
            ),
            (
                "assignment",
                source.replace("let key =", "let mut key =").replace(
                    "            drop(key)\n            if found",
                    "            key = \"different\"\n            drop(key)\n            if found",
                ),
            ),
            (
                "projected Drop",
                source.replace(
                    "    match map_new()",
                    "    let xs = [key]\n    drop(xs[0])\n    drop(xs)\n    match map_new()",
                ),
            ),
            (
                "capture",
                source.replace(
                    "            drop(key)\n            if found",
                    "            let reader = fn(ignored: i32) -> string { key }\n            drop(key)\n            if found",
                ),
            ),
        ] {
            let checked = crate::core::check_program(&parse(&candidate))
                .unwrap_or_else(|errors| panic!("{label}: {errors:?}"));
            assert!(
                checked
                    .resource_analysis(&NodeId("function:main".into()))
                    .unwrap()
                    .ordinary_map_owned_any_v2_cfg_receipt
                    .is_none(),
                "{label}"
            );
        }
    }

    #[test]
    fn ordinary_map_owned_any_v2_zero_miss_i32_owner_free_branch_receipt_is_exact() {
        use crate::core::cfg::Terminator;

        let source = include_str!(
            "../../../tests/fixtures/mir_ordinary_map_any_owner_v2_zero_miss_i32.mimi"
        );
        let checked = crate::core::check_program(&parse(source))
            .expect("exact ZeroMissI32 source checks before branch receipt admission");
        let owner = NodeId("function:main".into());
        let analysis = checked
            .resource_analysis(&owner)
            .expect("ZeroMissI32 ownership analysis");
        let receipt = analysis
            .ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .expect("exact ZeroMissI32 source receives owner-v2 Checker coverage");
        let observation = receipt
            .zero_miss_i32_observation_receipt
            .as_ref()
            .expect("the two pair.0 observations and exact formula are receipted");
        let flow = receipt
            .flow
            .as_ref()
            .expect("three short-circuit branches receive an owner-free flow receipt");
        let tail = receipt
            .settled_scalar_tail()
            .expect("Result-branch ZeroMissI32 carries settled scalar tail");

        assert_eq!(receipt.actions.len(), 7);
        assert_eq!(receipt.attempts.len(), 7);
        assert_eq!(receipt.found_observation_receipts.len(), 2);
        assert_eq!(observation.owner, owner);
        assert_ne!(observation.formula_node, observation.return_node);
        assert!(flow.reachable_blocks[&tail.return_block]
            .points
            .iter()
            .any(|(point, kind)| {
                point == &observation.return_node
                    && *kind == crate::core::cfg::CfgPointKind::Expression
            }));
        assert_eq!(
            flow.reachable_blocks
                .values()
                .filter(|block| matches!(block.terminator, Terminator::Return { .. }))
                .count(),
            1,
            "the Result-branch ZeroMissI32 graph exits at a single source Return block"
        );
        assert_eq!(
            flow.reachable_blocks
                .values()
                .filter(|block| {
                    block.points.iter().any(|(point, kind)| {
                        point == &observation.return_node
                            && *kind == crate::core::cfg::CfgPointKind::Expression
                    })
                })
                .count(),
            1,
            "the exact tail Load belongs to the unique tail return block"
        );
        assert_ne!(
            observation.hit_observation.operation,
            observation.miss_observation.operation
        );
        assert_eq!(flow.entry, flow.split);
        assert_eq!(flow.arm_edges.len(), 4);
        assert_eq!(flow.reachable_blocks.len(), flow.live_owners_in.len());
        assert_eq!(flow.reachable_blocks.len(), flow.live_owners_out.len());
        assert_eq!(flow.reachable_edges.len(), flow.live_owners_on_edge.len());
        assert!(flow.live_owners_out[&tail.split_block].is_empty());
        assert!(flow.live_owners_in[&tail.return_block].is_empty());
        assert!(flow.live_owners_out[&tail.return_block].is_empty());

        for selector in &observation.branch_selectors {
            assert!(flow.reachable_edges.contains_key(&selector.then_edge));
            assert!(flow.reachable_edges.contains_key(&selector.else_edge));
            if selector.block != tail.split_block {
                assert!(flow.live_owners_in[&selector.block].is_empty());
            }
            assert!(flow.live_owners_out[&selector.block].is_empty());
            assert!(flow.live_owners_on_edge[&selector.then_edge].is_empty());
            assert!(flow.live_owners_on_edge[&selector.else_edge].is_empty());
            assert_eq!(
                flow.reachable_edges[&selector.then_edge].to,
                selector.then_target
            );
            assert_eq!(
                flow.reachable_edges[&selector.else_edge].to,
                selector.else_target
            );
            assert!(matches!(
                &flow.reachable_blocks[&selector.block].terminator,
                Terminator::Branch {
                    condition,
                    then_edge,
                    else_edge,
                } if condition == &selector.condition
                    && then_edge == &selector.then_edge
                    && else_edge == &selector.else_edge
            ));
        }

        let extra_branch = source.replace(
            "let outcome: bool = hit_found && hit_payload == 0 && !miss_found && miss_payload == 0",
            "let outcome: bool = hit_found && hit_payload == 0 && (!miss_found || false) && miss_payload == 0",
        );
        assert_ne!(extra_branch, source, "negative source mutation must apply");
        assert!(
            crate::core::check_program(&parse(&extra_branch))
                .expect_err("an unproven short-circuit branch must fail closed")
                .iter()
                .any(|error| error.code.as_deref() == Some(crate::diagnostic::codes::E0200)),
            "an unsupported ZeroMiss unpack shape must retain the Checker E0200 diagnostic"
        );

        let extra_map_action = source.replace(
            "let miss_pair = map_get(root, \"absent\")\n\n        drop(empty)",
            "let miss_pair = map_get(root, \"absent\")\n        let ignored_size = map_size(root)\n\n        drop(empty)",
        );
        assert_ne!(
            extra_map_action, source,
            "negative source mutation must apply"
        );
        assert!(
            crate::core::check_program(&parse(&extra_map_action))
                .expect_err("an extra Map action must invalidate the exact checked-unpack profile")
                .iter()
                .any(|error| error.code.as_deref() == Some(crate::diagnostic::codes::E0200)),
            "the exact ZeroMiss profile rejects an added Map action with E0200"
        );
    }

    #[test]
    fn ordinary_map_owned_any_v2_rejects_branch_owner_actions_mismatches_and_cycles() {
        let branch_owner_action = parse(
            r#"
func main() -> i32 {
    match map_new() {
        Ok(root) => {
            let pair = map_get(root, "missing")
            let flag = true
            let observed = if flag {
                match map_new() {
                    Ok(branch_root) => {
                        drop(branch_root)
                        map_size(root)
                    }
                    Err(_status) => map_size(root),
                }
            } else {
                map_size(root)
            }
            drop(pair)
            drop(root)
            observed
        }
        Err(status) => status,
    }
}
"#,
        );
        let checked = crate::core::check_program(&branch_owner_action)
            .expect("balanced branch-local owner action typechecks before V2 admission");
        let analysis = checked
            .resource_analysis(&NodeId("function:main".into()))
            .expect("branch owner-action analysis");
        assert!(analysis.ordinary_map_owned_any_v2_cfg_receipt.is_none());

        let one_arm_result_drop = parse(
            r#"
func main() -> i32 {
    match map_new() {
        Ok(root) => {
            let pair = map_get(root, "missing")
            let flag = true
            if flag {
                drop(pair)
            } else {
                map_size(root)
            }
            drop(root)
            0
        }
        Err(status) => status,
    }
}
"#,
        );
        let checked = crate::core::check_program(&one_arm_result_drop)
            .expect("one-arm settlement is a source program before V2 admission");
        let analysis = checked
            .resource_analysis(&NodeId("function:main".into()))
            .expect("one-arm settlement analysis");
        assert!(
            analysis.ordinary_map_owned_any_v2_cfg_receipt.is_none(),
            "one-arm result settlement cannot reach the common owner join"
        );

        let looped = parse(
            r#"
func main() -> i32 {
    match map_new() {
        Ok(root) => {
            let pair = map_get(root, "missing")
            let flag = false
            while flag {
                map_size(root)
                break
            }
            drop(pair)
            drop(root)
            0
        }
        Err(status) => status,
    }
}
"#,
        );
        let checked = crate::core::check_program(&looped).expect("read-only loop typechecks");
        let analysis = checked
            .resource_analysis(&NodeId("function:main".into()))
            .expect("looped V2 analysis");
        assert!(analysis.ordinary_map_owned_any_v2_cfg_receipt.is_none());
    }

    #[test]
    fn ordinary_map_owned_any_v2_map_root_producer_carries_final_root_to_unique_caller() {
        use crate::core::ownership::OrdinaryMapOwnedAnyV2MapRootCallerProfileVersion;

        let checked = checked_map_root_program(
            r#"func direct_caller() -> i32 {
    let received_root = make_root()
    let count = map_size(received_root)
    drop(received_root)
    count
}"#,
            "",
            "direct_caller()",
        );
        let producer_owner = NodeId("function:make_root".into());
        let producer_analysis = checked
            .resource_analysis(&producer_owner)
            .expect("producer analysis");
        let cfg_receipt = producer_analysis
            .ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .expect("narrow producer V2 receipt");
        let producer_return = cfg_receipt
            .map_root_producer_return_receipt
            .as_ref()
            .expect("exact Map-root return lineage");
        let caller_receipt = cfg_receipt
            .map_root_producer_caller_receipt
            .as_ref()
            .expect("one direct caller settlement");

        assert_eq!(
            caller_receipt.profile_version,
            OrdinaryMapOwnedAnyV2MapRootCallerProfileVersion::V1
        );
        assert_eq!(
            producer_return.initial_root,
            producer_return.set_source_root
        );
        assert_eq!(
            producer_return.initial_root_local,
            producer_return.set_source_local
        );
        assert_ne!(producer_return.initial_root, producer_return.final_root);
        assert_eq!(caller_receipt.producer_owner, producer_owner);
        assert_eq!(
            caller_receipt.producer_map_set_operation,
            producer_return.map_set_operation
        );
        assert_eq!(
            caller_receipt.producer_return_value,
            producer_return.return_value
        );
        assert_eq!(
            caller_receipt.producer_final_local,
            producer_return.final_root_local
        );
        assert_eq!(
            caller_receipt.producer_final_binding_point,
            producer_return.final_root_binding_point
        );
        assert_eq!(caller_receipt.logical_root, producer_return.final_root);
        assert_eq!(caller_receipt.call_target, producer_owner);
        assert_eq!(
            caller_receipt.caller_owner,
            NodeId("function:direct_caller".into())
        );
        assert_eq!(
            caller_receipt.result_binding,
            caller_receipt.caller_root_local
        );
        assert_eq!(caller_receipt.result_type, producer_return.final_root_type);
        assert_eq!(
            caller_receipt.caller_root_type,
            producer_return.final_root_type
        );
        assert_eq!(caller_receipt.root_drop_place_index, 0);
        assert_eq!(caller_receipt.size_type, caller_receipt.caller_return_type);

        let caller_analysis = checked
            .resource_analysis(&caller_receipt.caller_owner)
            .expect("direct caller analysis");
        let [size_action, drop_action] =
            caller_analysis.ordinary_map_owned_any_v2_actions.as_slice()
        else {
            panic!("the proven caller receives exactly Size and Drop actions");
        };
        let caller_root =
            OrdinaryMapOwnedAnyV2Checker::resource_identity(&caller_receipt.caller_root_local);
        assert_eq!(size_action.kind, OrdinaryMapOwnedAnyV2ActionKind::Size);
        assert_eq!(
            size_action.profile_version,
            OrdinaryMapOwnedAnyV2ProfileVersion::V2
        );
        assert_eq!(size_action.point, caller_receipt.map_size_node);
        assert_eq!(size_action.local, caller_receipt.caller_root_local);
        assert_eq!(size_action.root, caller_root);
        assert_eq!(size_action.source_local, None);
        assert_eq!(size_action.source, None);
        assert_eq!(
            size_action.source_node,
            Some(caller_receipt.map_size_receiver_node.clone())
        );
        assert_eq!(
            size_action.source_type,
            Some(caller_receipt.caller_root_type.clone())
        );
        assert_eq!(size_action.result_type, None);
        assert_eq!(size_action.result_local, None);
        assert!(!size_action.payload_clone);
        assert_eq!(size_action.key, None);
        assert_eq!(size_action.key_type, None);
        assert_eq!(size_action.value, None);
        assert_eq!(size_action.value_type, None);
        assert_eq!(drop_action.kind, OrdinaryMapOwnedAnyV2ActionKind::Drop);
        assert_eq!(
            drop_action.profile_version,
            OrdinaryMapOwnedAnyV2ProfileVersion::V2
        );
        assert_eq!(drop_action.point, caller_receipt.root_drop_point);
        assert_eq!(drop_action.local, caller_receipt.caller_root_local);
        assert_eq!(drop_action.root, caller_root);
        assert_eq!(drop_action.source_local, None);
        assert_eq!(drop_action.source, None);
        assert_eq!(drop_action.source_node, None);
        assert_eq!(drop_action.source_type, None);
        assert_eq!(drop_action.result_type, None);
        assert_eq!(drop_action.result_local, None);
        assert!(!drop_action.payload_clone);
        assert_eq!(drop_action.key, None);
        assert_eq!(drop_action.key_type, None);
        assert_eq!(drop_action.value, None);
        assert_eq!(drop_action.value_type, None);

        let expected_size_attempt = OrdinaryMapOwnedAnyV2Attempt {
            kind: OrdinaryMapOwnedAnyV2AttemptKind::Size,
            point: caller_receipt.map_size_node.clone(),
            arguments: vec![caller_receipt.map_size_receiver_node.clone()],
            receiver_local: Some(caller_receipt.caller_root_local.clone()),
            result_local: None,
        };
        let expected_drop_attempt = OrdinaryMapOwnedAnyV2Attempt {
            kind: OrdinaryMapOwnedAnyV2AttemptKind::Drop,
            point: caller_receipt.root_drop_point.clone(),
            arguments: vec![caller_receipt.caller_root_local.0.clone()],
            receiver_local: Some(caller_receipt.caller_root_local.clone()),
            result_local: None,
        };
        assert_eq!(
            caller_analysis.ordinary_map_owned_any_v2_operation_attempts,
            BTreeSet::from([expected_size_attempt, expected_drop_attempt])
        );

        let (cfgs, bodies, signatures, analyses) = values_receipt_inputs(&checked);
        assert!(
            ordinary_map_owned_any_v2_map_root_producer_caller_receipt_is_exact(
                caller_receipt,
                &producer_owner,
                producer_return,
                &cfgs,
                &bodies,
                &signatures,
                checked.resolved_types(),
                checked.declaration_expression_bodies(),
                &analyses,
            )
        );
        let mut forged_target = caller_receipt.clone();
        forged_target.call_target = NodeId("function:forged_target".into());
        assert!(
            !ordinary_map_owned_any_v2_map_root_producer_caller_receipt_is_exact(
                &forged_target,
                &producer_owner,
                producer_return,
                &cfgs,
                &bodies,
                &signatures,
                checked.resolved_types(),
                checked.declaration_expression_bodies(),
                &analyses,
            )
        );
        let mut forged_root_lineage = caller_receipt.clone();
        forged_root_lineage.logical_root = ResourceId(NodeId("forged-map-root".into()));
        assert!(
            !ordinary_map_owned_any_v2_map_root_producer_caller_receipt_is_exact(
                &forged_root_lineage,
                &producer_owner,
                producer_return,
                &cfgs,
                &bodies,
                &signatures,
                checked.resolved_types(),
                checked.declaration_expression_bodies(),
                &analyses,
            )
        );
    }

    #[test]
    fn ordinary_map_owned_any_v2_map_root_get_any_caller_checks_string_and_all_owners() {
        use crate::core::ownership::OrdinaryMapOwnedAnyV2MapRootGetAnyCallerProfileVersion;

        let checked = checked_map_root_program(
            r#"func direct_caller() -> i32 {
    let received_root = make_root()
    let pair = map_get(received_root, "key")
    drop(received_root)
    let payload = unpack_string(pair.1)
    drop(pair)
    drop(payload)
    0
}"#,
            "",
            "direct_caller()",
        );
        let producer_owner = NodeId("function:make_root".into());
        let producer_analysis = checked
            .resource_analysis(&producer_owner)
            .expect("producer analysis");
        let producer_cfg_receipt = producer_analysis
            .ordinary_map_owned_any_v2_cfg_receipt
            .as_ref()
            .expect("producer V2 receipt");
        let producer_return = producer_cfg_receipt
            .map_root_producer_return_receipt
            .as_ref()
            .expect("producer's exact returned Map root");
        let receipt = producer_cfg_receipt
            .map_root_get_any_caller_receipt
            .as_ref()
            .expect("unique checked String GetAny caller");

        assert_eq!(
            receipt.profile_version,
            OrdinaryMapOwnedAnyV2MapRootGetAnyCallerProfileVersion::V1
        );
        assert_eq!(receipt.producer_owner, producer_owner);
        assert_eq!(receipt.call_target, producer_owner);
        assert_eq!(receipt.logical_root, producer_return.final_root);
        assert_eq!(
            receipt.producer_map_set_operation,
            producer_return.map_set_operation
        );
        assert_eq!(
            receipt.caller_owner,
            NodeId("function:direct_caller".into())
        );
        assert_eq!(receipt.caller_root_type, producer_return.final_root_type);
        assert_ne!(receipt.pair_drop_point, receipt.root_drop_point);
        assert_ne!(receipt.root_drop_point, receipt.string_drop_point);
        let caller_body = checked
            .resolved_body(&receipt.caller_owner)
            .expect("caller resolved body");
        let [_, get_statement, root_drop_statement, unpack_statement, pair_drop_statement, string_drop_statement] =
            caller_body.root.statements.as_slice()
        else {
            panic!("the Map-root/GetAny caller has the exact six-statement shape")
        };
        assert_eq!(get_statement.node_id, receipt.pair_binding_point);
        assert_eq!(root_drop_statement.node_id, receipt.root_drop_point);
        assert_eq!(unpack_statement.node_id, receipt.unpack_binding_point);
        assert_eq!(pair_drop_statement.node_id, receipt.pair_drop_point);
        assert_eq!(string_drop_statement.node_id, receipt.string_drop_point);
        assert_eq!(
            receipt.caller_return_type,
            crate::core::ir::primitive_type_id(crate::core::PrimitiveType::I32)
        );
        assert_eq!(
            receipt.caller_return_literal,
            crate::core::ir::ResolvedLiteral::Int(0)
        );

        let caller_analysis = checked
            .resource_analysis(&receipt.caller_owner)
            .expect("caller analysis");
        assert_eq!(
            caller_analysis
                .ordinary_map_owned_any_v2_actions
                .iter()
                .map(|action| action.kind)
                .collect::<Vec<_>>(),
            vec![
                OrdinaryMapOwnedAnyV2ActionKind::GetAny,
                OrdinaryMapOwnedAnyV2ActionKind::Drop,
            ]
        );
        assert_eq!(
            caller_analysis
                .ordinary_map_owned_any_v2_operation_attempts
                .iter()
                .map(|attempt| attempt.kind)
                .collect::<BTreeSet<_>>(),
            BTreeSet::from([
                OrdinaryMapOwnedAnyV2AttemptKind::GetAny,
                OrdinaryMapOwnedAnyV2AttemptKind::Drop,
            ])
        );

        let (cfgs, bodies, signatures, analyses) = values_receipt_inputs(&checked);
        assert!(
            ordinary_map_owned_any_v2_map_root_get_any_caller_receipt_is_exact(
                receipt,
                &producer_owner,
                producer_return,
                &cfgs,
                &bodies,
                &signatures,
                checked.resolved_types(),
                checked.declaration_expression_bodies(),
                &analyses,
            )
        );
        let mut forged_string_drop = receipt.clone();
        forged_string_drop.string_drop_point = forged_string_drop.root_drop_point.clone();
        assert!(
            !ordinary_map_owned_any_v2_map_root_get_any_caller_receipt_is_exact(
                &forged_string_drop,
                &producer_owner,
                producer_return,
                &cfgs,
                &bodies,
                &signatures,
                checked.resolved_types(),
                checked.declaration_expression_bodies(),
                &analyses,
            )
        );
        let mut forged_string_drop_place = receipt.clone();
        forged_string_drop_place.string_drop_place_index += 1;
        assert!(
            !ordinary_map_owned_any_v2_map_root_get_any_caller_receipt_is_exact(
                &forged_string_drop_place,
                &producer_owner,
                producer_return,
                &cfgs,
                &bodies,
                &signatures,
                checked.resolved_types(),
                checked.declaration_expression_bodies(),
                &analyses,
            ),
            "the payload Drop's place index is independently rederived"
        );

        fn edit_call(
            bodies: &mut BTreeMap<NodeId, ResolvedBody>,
            owner: &str,
            statement_index: usize,
            edit: impl FnOnce(&mut crate::core::ir::ResolvedCall, &mut Vec<crate::core::ir::EffectId>),
        ) {
            let body = bodies
                .get_mut(&NodeId(owner.to_string()))
                .expect("tamper target body");
            let ResolvedStmtKind::Bind {
                initializer: Some(expression),
                ..
            } = &mut body.root.statements[statement_index].kind
            else {
                panic!("tamper target is a direct call binding")
            };
            let crate::core::ir::ResolvedExpr { kind, effects, .. } = expression;
            let ResolvedExprKind::Call(call) = kind else {
                panic!("tamper target initializer is a call")
            };
            edit(call, effects);
        }

        fn assert_tampered_source_rejected(
            checked: &crate::core::CheckedProgram,
            mutate: impl FnOnce(&mut BTreeMap<NodeId, ResolvedBody>),
        ) {
            let (cfgs, mut bodies, signatures, analyses) = values_receipt_inputs(checked);
            let producer_owner = NodeId("function:make_root".into());
            let producer_return = analyses
                .get(&producer_owner)
                .and_then(|analysis| analysis.ordinary_map_owned_any_v2_cfg_receipt.as_ref())
                .and_then(|receipt| receipt.map_root_producer_return_receipt.as_ref())
                .expect("original exact producer return")
                .clone();
            mutate(&mut bodies);
            assert!(
                collect_ordinary_map_owned_any_v2_map_root_get_any_caller_receipt(
                    &producer_owner,
                    &producer_return,
                    &cfgs,
                    &bodies,
                    &signatures,
                    checked.resolved_types(),
                    checked.declaration_expression_bodies(),
                    &analyses,
                )
                .is_none(),
                "forged checked call metadata must withhold the whole-program receipt"
            );
        }

        assert_tampered_source_rejected(&checked, |bodies| {
            edit_call(bodies, "function:direct_caller", 0, |call, _| {
                call.result =
                    crate::core::ir::primitive_type_id(crate::core::PrimitiveType::String);
            });
        });
        assert_tampered_source_rejected(&checked, |bodies| {
            edit_call(bodies, "function:direct_caller", 0, |call, effects| {
                let forged = crate::core::ir::EffectId::new("unknown").unwrap();
                call.effects = vec![forged.clone()];
                *effects = vec![forged];
            });
        });
        assert_tampered_source_rejected(&checked, |bodies| {
            edit_call(bodies, "function:direct_caller", 0, |call, _| {
                call.permission = Some(crate::core::ir::Permission::View);
            });
        });
        assert_tampered_source_rejected(&checked, |bodies| {
            edit_call(bodies, "function:direct_caller", 0, |call, _| {
                call.session.push(crate::core::ir::SessionTransition {
                    endpoint: ResolvedLocalId(NodeId("forged-session-endpoint".into())),
                    before: crate::core::ir::SessionResidualId::new("forged-before").unwrap(),
                    after: crate::core::ir::SessionResidualId::new("forged-after").unwrap(),
                    terminal: false,
                });
            });
        });
        assert_tampered_source_rejected(&checked, |bodies| {
            edit_call(bodies, "function:direct_caller", 0, |_, effects| {
                effects.clear();
            });
        });
        assert_tampered_source_rejected(&checked, |bodies| {
            let body = bodies
                .get_mut(&NodeId("function:direct_caller".into()))
                .unwrap();
            let ResolvedStmtKind::Bind {
                pattern:
                    ResolvedPattern {
                        kind: ResolvedPatternKind::Binding { local, .. },
                        ..
                    },
                ..
            } = &body.root.statements[0].kind
            else {
                panic!("returned Map root has a direct binding")
            };
            body.locals.get_mut(local).unwrap().mutable = true;
        });
        assert_tampered_source_rejected(&checked, |bodies| {
            edit_call(bodies, "function:direct_caller", 1, |call, effects| {
                let forged = crate::core::ir::EffectId::new("unknown").unwrap();
                call.effects = vec![forged.clone()];
                *effects = vec![forged];
            });
        });
        assert_tampered_source_rejected(&checked, |bodies| {
            edit_call(bodies, "function:direct_caller", 1, |call, _| {
                call.permission = Some(crate::core::ir::Permission::View);
            });
        });
        assert_tampered_source_rejected(&checked, |bodies| {
            edit_call(bodies, "function:direct_caller", 1, |call, _| {
                call.session.push(crate::core::ir::SessionTransition {
                    endpoint: ResolvedLocalId(NodeId("forged-session-endpoint".into())),
                    before: crate::core::ir::SessionResidualId::new("forged-before").unwrap(),
                    after: crate::core::ir::SessionResidualId::new("forged-after").unwrap(),
                    terminal: false,
                });
            });
        });
        assert_tampered_source_rejected(&checked, |bodies| {
            edit_call(bodies, "function:direct_caller", 1, |_, effects| {
                *effects = vec![crate::core::ir::EffectId::new("unknown").unwrap()];
            });
        });
        assert_tampered_source_rejected(&checked, |bodies| {
            edit_call(bodies, "function:make_root", 1, |call, _| {
                call.result =
                    crate::core::ir::primitive_type_id(crate::core::PrimitiveType::String);
            });
        });
        assert_tampered_source_rejected(&checked, |bodies| {
            edit_call(bodies, "function:make_root", 2, |call, effects| {
                let forged = crate::core::ir::EffectId::new("unknown").unwrap();
                call.effects = vec![forged.clone()];
                *effects = vec![forged];
            });
        });
        assert_tampered_source_rejected(&checked, |bodies| {
            edit_call(bodies, "function:make_root", 2, |call, _| {
                call.permission = Some(crate::core::ir::Permission::View);
            });
        });
        assert_tampered_source_rejected(&checked, |bodies| {
            edit_call(bodies, "function:make_root", 2, |call, _| {
                call.session.push(crate::core::ir::SessionTransition {
                    endpoint: ResolvedLocalId(NodeId("forged-session-endpoint".into())),
                    before: crate::core::ir::SessionResidualId::new("forged-before").unwrap(),
                    after: crate::core::ir::SessionResidualId::new("forged-after").unwrap(),
                    terminal: false,
                });
            });
        });

        let (cfgs, bodies, mut signatures, analyses) = values_receipt_inputs(&checked);
        let producer_owner = NodeId("function:make_root".into());
        let producer_return = analyses
            .get(&producer_owner)
            .and_then(|analysis| analysis.ordinary_map_owned_any_v2_cfg_receipt.as_ref())
            .and_then(|receipt| receipt.map_root_producer_return_receipt.as_ref())
            .expect("original exact producer return")
            .clone();
        signatures.get_mut(&producer_owner).unwrap().effects.clear();
        assert!(
            collect_ordinary_map_owned_any_v2_map_root_get_any_caller_receipt(
                &producer_owner,
                &producer_return,
                &cfgs,
                &bodies,
                &signatures,
                checked.resolved_types(),
                checked.declaration_expression_bodies(),
                &analyses,
            )
            .is_none()
        );
    }

    #[test]
    fn ordinary_map_owned_any_v2_map_root_get_any_caller_withholds_unsupported_shapes() {
        let producer_owner = NodeId("function:make_root".into());
        let unsupported = [
            (
                "root drop is after the String unpack",
                r#"func direct_caller() -> i32 {
    let received_root = make_root()
    let pair = map_get(received_root, "key")
    let payload = unpack_string(pair.1)
    drop(pair)
    drop(received_root)
    drop(payload)
    0
}"#,
                "",
            ),
            (
                "root is not dropped",
                r#"func direct_caller() -> i32 {
    let received_root = make_root()
    let pair = map_get(received_root, "key")
    let payload = unpack_string(pair.1)
    drop(pair)
    drop(payload)
    0
}"#,
                "",
            ),
            (
                "GetAny tuple is not dropped",
                r#"func direct_caller() -> i32 {
    let received_root = make_root()
    let pair = map_get(received_root, "key")
    drop(received_root)
    let payload = unpack_string(pair.1)
    drop(payload)
    0
}"#,
                "",
            ),
            (
                "payload is not settled",
                r#"func direct_caller() -> i32 {
    let received_root = make_root()
    let pair = map_get(received_root, "key")
    let payload = unpack_string(pair.1)
    drop(pair)
    drop(received_root)
    0
}"#,
                "",
            ),
            (
                "unpack is checked for a non-String payload",
                r#"func direct_caller() -> i32 {
    let received_root = make_root()
    let pair = map_get(received_root, "key")
    drop(received_root)
    let payload = pair.1 as i32
    drop(pair)
    drop(payload)
    0
}"#,
                "",
            ),
            (
                "key differs from producer Set",
                r#"func direct_caller() -> i32 {
    let received_root = make_root()
    let pair = map_get(received_root, "other")
    let payload = unpack_string(pair.1)
    drop(pair)
    drop(received_root)
    drop(payload)
    0
}"#,
                "",
            ),
            (
                "a second direct caller exists",
                r#"func direct_caller() -> i32 {
    let received_root = make_root()
    let pair = map_get(received_root, "key")
    let payload = unpack_string(pair.1)
    drop(pair)
    drop(received_root)
    drop(payload)
    0
}"#,
                r#"func second_caller() -> i32 {
    let received_root = make_root()
    let pair = map_get(received_root, "key")
    let payload = unpack_string(pair.1)
    drop(pair)
    drop(received_root)
    drop(payload)
    0
}"#,
            ),
        ];

        for (label, caller, extra_items) in unsupported {
            let source = format!(
                "{}\n{}\n{}\nfunc main() -> i32 {{ direct_caller() }}",
                map_root_producer_source(),
                caller,
                extra_items
            );
            match crate::core::check_program(&parse_stdlib(&source)) {
                Ok(checked) => assert!(
                    checked
                        .resource_analysis(&producer_owner)
                        .and_then(|analysis| analysis
                            .ordinary_map_owned_any_v2_cfg_receipt
                            .as_ref())
                        .and_then(|receipt| receipt.map_root_get_any_caller_receipt.as_ref())
                        .is_none(),
                    "{label}: unsupported GetAny bridge must not receive Checker authority"
                ),
                Err(errors) => assert!(
                    !errors.is_empty(),
                    "{label}: unsupported owner settlement must fail closed"
                ),
            }
        }
    }

    #[test]
    fn ordinary_map_owned_any_v2_map_root_producer_withholds_incomplete_or_nonunique_settlement() {
        let cases = [
            (
                "caller omits root Drop",
                r#"func direct_caller() -> i32 {
    let received_root = make_root()
    let count = map_size(received_root)
    count
}"#,
                "",
                0,
                0,
            ),
            (
                "caller performs an extra root read",
                r#"func direct_caller() -> i32 {
    let received_root = make_root()
    let count = map_size(received_root)
    let second_count = map_size(received_root)
    drop(received_root)
    count + second_count
}"#,
                "",
                1,
                0,
            ),
            (
                "a second direct caller exists",
                r#"func direct_caller() -> i32 {
    let received_root = make_root()
    let count = map_size(received_root)
    drop(received_root)
    count
}"#,
                r#"func second_caller() -> i32 {
    let received_root = make_root()
    let count = map_size(received_root)
    drop(received_root)
    count
}"#,
                1,
                1,
            ),
        ];
        let producer_owner = NodeId("function:make_root".into());
        for (
            label,
            caller,
            extra_items,
            expected_direct_drop_attempts,
            expected_second_drop_attempts,
        ) in cases
        {
            let source = format!(
                "{}\n{}\n{}\nfunc main() -> i32 {{ direct_caller() }}",
                map_root_producer_source(),
                caller,
                extra_items
            );
            match crate::core::check_program(&parse_stdlib(&source)) {
                Ok(checked) => {
                    assert!(
                        checked
                            .resource_analysis(&producer_owner)
                            .and_then(|analysis| analysis
                                .ordinary_map_owned_any_v2_cfg_receipt
                                .as_ref())
                            .and_then(|receipt| receipt.map_root_producer_caller_receipt.as_ref())
                            .is_none(),
                        "{label}: incomplete or non-unique caller must not receive a root receipt"
                    );
                    for (owner, expected_drop_attempts) in [
                        ("function:direct_caller", expected_direct_drop_attempts),
                        ("function:second_caller", expected_second_drop_attempts),
                    ] {
                        let caller_analysis = checked.resource_analysis(&NodeId(owner.into()));
                        if let Some(caller_analysis) = caller_analysis {
                            assert!(
                                caller_analysis.ordinary_map_owned_any_v2_actions.is_empty(),
                                "{label}: rejected caller shape must not synthesize V2 actions"
                            );
                            assert_eq!(
                                caller_analysis
                                    .ordinary_map_owned_any_v2_operation_attempts
                                    .iter()
                                    .filter(|attempt| {
                                        attempt.kind == OrdinaryMapOwnedAnyV2AttemptKind::Drop
                                    })
                                    .count(),
                                expected_drop_attempts,
                                "{label}: Drop attempts must match explicit source Drops"
                            );
                        } else {
                            assert_eq!(
                                expected_drop_attempts, 0,
                                "{label}: an absent caller analysis cannot have source Drop attempts"
                            );
                        }
                    }
                }
                Err(errors) => assert!(
                    !errors.is_empty(),
                    "{label}: rejected source must retain a diagnostic"
                ),
            }
        }
    }

    #[test]
    fn ordinary_map_owned_any_v2_map_root_producer_rejects_early_drop_and_function_reference() {
        let producer_owner = NodeId("function:make_root".into());
        let early_drop_source = r#"
func make_root() -> Record {
    let payload = "owned value"
    let empty = map_new()
    let final_root = map_set(empty, "key", payload)
    drop(empty)
    drop(final_root)
    drop(payload)
    final_root
}
func direct_caller() -> i32 {
    let received_root = make_root()
    let count = map_size(received_root)
    drop(received_root)
    count
}
func main() -> i32 { direct_caller() }
"#;
        match crate::core::check_program(&parse_stdlib(early_drop_source)) {
            Ok(checked) => assert!(
                checked
                    .resource_analysis(&producer_owner)
                    .and_then(|analysis| analysis.ordinary_map_owned_any_v2_cfg_receipt.as_ref())
                    .and_then(|receipt| receipt.map_root_producer_return_receipt.as_ref())
                    .is_none(),
                "a producer that explicitly drops its final root cannot return its lineage"
            ),
            Err(errors) => assert!(
                !errors.is_empty(),
                "early producer Drop must either diagnose or leave its root unreceipted"
            ),
        }

        let function_reference_source = format!(
            "{}\n{}\n{}\nfunc main() -> i32 {{ direct_caller() }}",
            map_root_producer_source(),
            r#"func direct_caller() -> i32 {
    let received_root = make_root()
    let count = map_size(received_root)
    drop(received_root)
    count
}"#,
            r#"func function_reference() -> i32 {
    let maker = make_root
    0
}"#
        );
        match crate::core::check_program(&parse_stdlib(&function_reference_source)) {
            Ok(checked) => assert!(
                checked
                    .resource_analysis(&producer_owner)
                    .and_then(|analysis| analysis.ordinary_map_owned_any_v2_cfg_receipt.as_ref())
                    .and_then(|receipt| receipt.map_root_producer_caller_receipt.as_ref())
                    .is_none(),
                "a first-class producer reference must withhold the unique caller receipt"
            ),
            Err(errors) => assert!(
                !errors.is_empty(),
                "unsupported producer function references must fail closed"
            ),
        }
    }

    #[test]
    fn ordinary_map_owned_any_v2_map_root_producer_counts_declaration_expression_calls_and_refs() {
        let producer_owner = NodeId("function:make_root".into());
        let cases = [
            (
                "constant initializer call",
                "hidden_root",
                "const hidden_root = make_root()",
                r#"func hidden_caller() -> i32 {
    let received_root = hidden_root
    let count = map_size(received_root)
    drop(received_root)
    count
}"#,
                "call",
            ),
            (
                "constant initializer closure reference",
                "hidden_factory",
                "const hidden_factory = fn() -> Record { make_root() }",
                r#"func hidden_caller() -> i32 {
    let factory = hidden_factory
    let received_root = factory()
    let count = map_size(received_root)
    drop(received_root)
    count
}"#,
                "reference closure",
            ),
        ];

        for (label, constant_name, initializer, hidden_caller, expected_reference) in cases {
            let extra_items = format!("{initializer}\n{hidden_caller}");
            let checked = checked_map_root_program(
                r#"func direct_caller() -> i32 {
    let received_root = make_root()
    let count = map_size(received_root)
    drop(received_root)
    count
}"#,
                &extra_items,
                "direct_caller() + hidden_caller()",
            );
            let declaration = checked
                .declaration_expression_bodies()
                .values()
                .find(|root| root.owner == NodeId(format!("constant:{constant_name}")))
                .unwrap_or_else(|| panic!("{label}: missing const declaration body"));
            let declaration_body = declaration.body.as_ref().unwrap_or_else(|errors| {
                panic!("{label}: declaration body did not lower: {errors:?}")
            });
            assert!(
                declaration_body.resolved_calls.values().any(
                    |callee| matches!(callee, ResolvedCallee::Function(target) if target == &producer_owner)
                ),
                "{label}: the declaration body must retain the producer call for the census"
            );

            let producer_receipt = checked
                .resource_analysis(&producer_owner)
                .and_then(|analysis| analysis.ordinary_map_owned_any_v2_cfg_receipt.as_ref())
                .expect("the producer return itself remains Checker-receipted");
            assert!(
                producer_receipt.map_root_producer_return_receipt.is_some(),
                "{label}: declaration expression must not invalidate the local producer proof"
            );
            assert!(
                producer_receipt.map_root_producer_caller_receipt.is_none(),
                "{label}: a declaration-expression {expected_reference} must withhold unique-caller authority"
            );
        }
    }

